options.styles:
& {
  display: block;
  container-type: inline-size;
  container-name: logocontainer;
}

& .dt-row {
  height: 100%;
  display: flex;
  padding: 0;
  align-items: center;
}

& .dt-row .logo {
  width: 100%;
  height: 100%;
  background-repeat: no-repeat;
  background-size: contain;
  background-position: center;
}

& .dt-row .description {
  font-size: larger;
  align-self: flex-start;
  margin-top: 2rem;
  width: 30%;
}

@container logocontainer (max-width: 500px) {
  & .dt-row {
    flex-direction: column;
  }

  & .dt-row .description {
    align-self: center;
    margin: 0;
    width: auto;
  }
}
